/**
 * Functions for authenticating users via Steam to play on a game server
 *
 * @see https://partner.steamgames.com/doc/api/ISteamGameServerStats
 */
export interface ISteamGameServerStats {
    /**
     * downloads stats for the user
     * returns a GSStatsReceived_t callback when completed
     * if the user has no stats, GSStatsReceived_t.m_eResult will be set to k_EResultFail
     * these stats will only be auto-updated for clients playing on the server. For other
     * users you'll need to call RequestUserStats() again to refresh any data
     *
     * @param steamIDUser `CSteamID`
     * @returns A Promise of the `GSStatsReceived_t` call result (rejects if Steam returns k_uAPICallInvalid or an I/O failure).
     * C++: `SteamAPICall_t RequestUserStats( CSteamID steamIDUser )`
     * @see https://partner.steamgames.com/doc/api/ISteamGameServerStats#RequestUserStats
     */
    RequestUserStats(steamIDUser: bigint | number): Promise<GSStatsReceived_t>
    /**
     * requests stat information for a user, usable after a successful call to RequestUserStats()
     *
     * @param steamIDUser `CSteamID`
     * @param pchName `const char *`
     * @param pData `int32 *`. Output: returned in the result object.
     * C++: `bool GetUserStat( CSteamID steamIDUser, const char * pchName, int32 * pData )`
     * @see https://partner.steamgames.com/doc/api/ISteamGameServerStats#GetUserStat
     */
    GetUserStatInt32(steamIDUser: bigint | number, pchName: string): { result: boolean; pData: number }
    /**
     * @param steamIDUser `CSteamID`
     * @param pchName `const char *`
     * @param pData `float *`. Output: returned in the result object.
     * C++: `bool GetUserStat( CSteamID steamIDUser, const char * pchName, float * pData )`
     * @see https://partner.steamgames.com/doc/api/ISteamGameServerStats#GetUserStat
     */
    GetUserStatFloat(steamIDUser: bigint | number, pchName: string): { result: boolean; pData: number }
    /**
     * @param steamIDUser `CSteamID`
     * @param pchName `const char *`
     * @param pbAchieved `bool *`. Output: returned in the result object.
     * C++: `bool GetUserAchievement( CSteamID steamIDUser, const char * pchName, bool * pbAchieved )`
     * @see https://partner.steamgames.com/doc/api/ISteamGameServerStats#GetUserAchievement
     */
    GetUserAchievement(steamIDUser: bigint | number, pchName: string): { result: boolean; pbAchieved: boolean }
    /**
     * @param steamIDUser `CSteamID`
     * @param pchName `const char *`
     * @param nData `int32`
     * C++: `bool SetUserStat( CSteamID steamIDUser, const char * pchName, int32 nData )`
     * @see https://partner.steamgames.com/doc/api/ISteamGameServerStats#SetUserStat
     */
    SetUserStatInt32(steamIDUser: bigint | number, pchName: string, nData: number): boolean
    /**
     * @param steamIDUser `CSteamID`
     * @param pchName `const char *`
     * @param fData `float`
     * C++: `bool SetUserStat( CSteamID steamIDUser, const char * pchName, float fData )`
     * @see https://partner.steamgames.com/doc/api/ISteamGameServerStats#SetUserStat
     */
    SetUserStatFloat(steamIDUser: bigint | number, pchName: string, fData: number): boolean
    /**
     * @param steamIDUser `CSteamID`
     * @param pchName `const char *`
     * @param flCountThisSession `float`
     * @param dSessionLength `double`
     * C++: `bool UpdateUserAvgRateStat( CSteamID steamIDUser, const char * pchName, float flCountThisSession, double dSessionLength )`
     * @see https://partner.steamgames.com/doc/api/ISteamGameServerStats#UpdateUserAvgRateStat
     */
    UpdateUserAvgRateStat(steamIDUser: bigint | number, pchName: string, flCountThisSession: number, dSessionLength: number): boolean
    /**
     * @param steamIDUser `CSteamID`
     * @param pchName `const char *`
     * C++: `bool SetUserAchievement( CSteamID steamIDUser, const char * pchName )`
     * @see https://partner.steamgames.com/doc/api/ISteamGameServerStats#SetUserAchievement
     */
    SetUserAchievement(steamIDUser: bigint | number, pchName: string): boolean
    /**
     * @param steamIDUser `CSteamID`
     * @param pchName `const char *`
     * C++: `bool ClearUserAchievement( CSteamID steamIDUser, const char * pchName )`
     * @see https://partner.steamgames.com/doc/api/ISteamGameServerStats#ClearUserAchievement
     */
    ClearUserAchievement(steamIDUser: bigint | number, pchName: string): boolean
    /**
     * Store the current data on the server, will get a GSStatsStored_t callback when set.
     *
     * If the callback has a result of k_EResultInvalidParam, one or more stats
     * uploaded has been rejected, either because they broke constraints
     * or were out of date. In this case the server sends back updated values.
     * The stats should be re-iterated to keep in sync.
     *
     * @param steamIDUser `CSteamID`
     * @returns A Promise of the `GSStatsStored_t` call result (rejects if Steam returns k_uAPICallInvalid or an I/O failure).
     * C++: `SteamAPICall_t StoreUserStats( CSteamID steamIDUser )`
     * @see https://partner.steamgames.com/doc/api/ISteamGameServerStats#StoreUserStats
     */
    StoreUserStats(steamIDUser: bigint | number): Promise<GSStatsStored_t>
}

